sections.code:
console.log("¡Hola, JavaScript!");
const lenguaje = "JavaScript";
console.log("Estoy aprendiendo " + lenguaje);

// ECMAScript define las reglas del lenguaje.
const nombre = "Ada";
const saludo = `Hola, ${nombre}`;
console.log(saludo); // Sintaxis del lenguaje

// El entorno aporta APIs diferentes.
console.log(typeof Promise); // "function"
console.log(typeof document); // "undefined" en Node.js
// document pertenece al navegador, no al núcleo de ECMAScript.

exampleVariants.code:
// ECMAScript define las reglas del lenguaje.
const nombre = "Ada";
const saludo = `Hola, ${nombre}`;
console.log(saludo); // Sintaxis del lenguaje

// El entorno aporta APIs diferentes.
console.log(typeof Promise); // "function"
console.log(typeof document); // "undefined" en Node.js
// document pertenece al navegador, no al núcleo de ECMAScript.

// El mismo lenguaje puede ejecutarse en distintos entornos.
const total = [10, 20, 30].reduce((suma, n) => suma + n, 0);
console.log(total); // 60

// En el navegador existe window; en Node.js existe globalThis.
console.log(globalThis === globalThis); // true
// Consultá la documentación del entorno antes de usar una API específica.

