exampleVariants.code:
async function cargarPosts() {
  const respuesta = await fetch("https://jsonplaceholder.typicode.com/posts");
  if (!respuesta.ok) throw new Error(`HTTP ${respuesta.status}`);
  const posts = await respuesta.json();
  console.log(posts.slice(0, 3));
}
cargarPosts().catch(console.error);

const url = new URL("https://jsonplaceholder.typicode.com/posts");
url.searchParams.set("userId", "1");
fetch(url).then(r => r.json()).then(console.log);

fetch("https://jsonplaceholder.typicode.com/posts/1")
  .then(response => {
    if (!response.ok) throw new Error(`Respuesta HTTP ${response.status}`);
    return response.text();
  })
  .then(texto => console.log(texto.slice(0, 80)))
  .catch(console.error);

const controlador = new AbortController();
const temporizador = setTimeout(() => controlador.abort(), 3000);
fetch("https://jsonplaceholder.typicode.com/posts", { signal: controlador.signal })
  .then(r => r.json()).then(console.log).catch(console.error)
  .finally(() => clearTimeout(temporizador));

