const archivo = document.querySelector("input[type=file]")?.files?.[0];
if (archivo) {
  const url = URL.createObjectURL(archivo);
  document.querySelector("#vista-previa")?.setAttribute("src", url);
  // Revocá la URL cuando ya no se necesite: URL.revokeObjectURL(url).
}

