const solicitud = indexedDB.open("Biblioteca", 1);
solicitud.onupgradeneeded = () => {
  const db = solicitud.result;
  if (!db.objectStoreNames.contains("notas")) db.createObjectStore("notas", { keyPath: "id", autoIncrement: true });
};
solicitud.onsuccess = () => console.log("Base abierta");
solicitud.onerror = () => console.error(solicitud.error);

const request = indexedDB.open("Biblioteca", 1);
request.onsuccess = () => {
  const db = request.result;
  const tx = db.transaction("notas", "readwrite");
  tx.objectStore("notas").add({ texto: "Repasar IndexedDB" });
  tx.oncomplete = () => db.close();
};

